import { useState, useEffect } from "react";
import { createPortal } from "react-dom";
import { useNavigate, useLocation } from "react-router-dom";
import { useLenis, scrollToElement } from "../context/smoothScroll";
import { useScrollSpy } from "../hooks/useScrollSpy";
import "./Navbar.css";

const Navbar = () => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const lenisRef = useLenis();
  const activeSection = useScrollSpy(location.pathname !== "/");

  useEffect(() => {
    if (location.pathname === "/" && location.hash) {
      const id = location.hash.replace("#", "");
      const timer = setTimeout(() => {
        scrollToElement(lenisRef, document.getElementById(id));
      }, 300);
      return () => clearTimeout(timer);
    }
  }, [location.pathname, location.hash, lenisRef]);

  useEffect(() => {
    if (!isMobileMenuOpen) return;

    const lenis = lenisRef?.current;
    document.body.style.overflow = "hidden";
    lenis?.stop();

    return () => {
      document.body.style.overflow = "";
      lenis?.start();
    };
  }, [isMobileMenuOpen, lenisRef]);

  const handleNavClick = (e, sectionId) => {
    e.preventDefault();

    if (location.pathname !== "/") {
      setIsMobileMenuOpen(false);
      navigate(`/#${sectionId}`);
      return;
    }

    setIsMobileMenuOpen(false);
    scrollToElement(lenisRef, document.getElementById(sectionId));
  };

  const mobileMenu = isMobileMenuOpen
    ? createPortal(
        <div
          className="md:hidden fixed inset-0 z-[200] bg-c-primary flex flex-col pt-24 px-margin-mobile pb-10 overflow-y-auto"
          role="dialog"
          aria-modal="true"
          aria-label="Mobile navigation"
        >
          <nav className="flex flex-col gap-6 mt-4">
            <a className={activeSection === 'home' ? `font-body text-[18px] font-medium text-white` : `font-body text-[18px] font-medium text-white/70`} href="#home" onClick={(e) => { handleNavClick(e, 'home'); }}>Home</a>
            <a className={activeSection === 'products' ? `font-body text-[18px] font-medium text-white` : `font-body text-[18px] font-medium text-white/70`} href="#products" onClick={(e) => { handleNavClick(e, 'products'); }}>Optical Shop</a>
            <a className={activeSection === 'services' ? `font-body text-[18px] font-medium text-white` : `font-body text-[18px] font-medium text-white/70`} href="#services" onClick={(e) => { handleNavClick(e, 'services'); }}>Services</a>
            <a className={activeSection === 'about' ? `font-body text-[18px] font-medium text-white` : `font-body text-[18px] font-medium text-white/70`} href="#about" onClick={(e) => { handleNavClick(e, 'about'); }}>Appointments</a>
          </nav>
          <div className="mt-auto pt-10">
            <button onClick={() => { window.dispatchEvent(new Event('open-booking-modal')); setIsMobileMenuOpen(false); }} className="btn-primary w-full text-center py-4 text-[16px]">
              Book Consultation
            </button>
          </div>
        </div>,
        document.body,
      )
    : null;

  return (
    <>
    <header
      className={`fixed top-0 w-full border-b border-white/10 shadow-[0_4px_30px_rgba(0,0,0,0.15)] transition-colors duration-300 ${isMobileMenuOpen ? "z-[210] bg-c-primary" : "z-50 bg-c-primary/95 backdrop-blur-md"}`}
      id="main-header"
    >
      <div className="flex justify-between items-center px-margin-mobile md:px-margin-desktop py-4 max-w-container-max mx-auto">
        <div className="flex items-center gap-4">
          <img
            alt="Jaiswal Eye Care Center Logo"
            className="h-10 w-10 object-contain rounded-full shadow-sm"
            src="data:image/png;base64,"
          />
          <span className="font-headline-sm text-white tracking-tight hidden sm:block">
            Jaiswal Eye Care
          </span>
        </div>
        <nav className="hidden md:flex items-center gap-10">
          <a className={activeSection === 'home' ? `font-body text-[15px] font-medium text-white relative after:content-[''] after:absolute after:-bottom-1 after:left-0 after:w-full after:h-[2px] after:bg-c-accent transition-all` : `font-body text-[15px] font-medium text-white/70 hover:text-white relative after:content-[''] after:absolute after:-bottom-1 after:left-0 after:w-0 hover:after:w-full after:h-[2px] after:bg-c-accent after:transition-all after:duration-300 transition-colors duration-300`} href="#home" onClick={(e) => handleNavClick(e, 'home')}>Home</a>
          <a className={activeSection === 'products' ? `font-body text-[15px] font-medium text-white relative after:content-[''] after:absolute after:-bottom-1 after:left-0 after:w-full after:h-[2px] after:bg-c-accent transition-all` : `font-body text-[15px] font-medium text-white/70 hover:text-white relative after:content-[''] after:absolute after:-bottom-1 after:left-0 after:w-0 hover:after:w-full after:h-[2px] after:bg-c-accent after:transition-all after:duration-300 transition-colors duration-300`} href="#products" onClick={(e) => handleNavClick(e, 'products')}>Optical Shop</a>
          <a className={activeSection === 'services' ? `font-body text-[15px] font-medium text-white relative after:content-[''] after:absolute after:-bottom-1 after:left-0 after:w-full after:h-[2px] after:bg-c-accent transition-all` : `font-body text-[15px] font-medium text-white/70 hover:text-white relative after:content-[''] after:absolute after:-bottom-1 after:left-0 after:w-0 hover:after:w-full after:h-[2px] after:bg-c-accent after:transition-all after:duration-300 transition-colors duration-300`} href="#services" onClick={(e) => handleNavClick(e, 'services')}>Services</a>
          <a className={activeSection === 'about' ? `font-body text-[15px] font-medium text-white relative after:content-[''] after:absolute after:-bottom-1 after:left-0 after:w-full after:h-[2px] after:bg-c-accent transition-all` : `font-body text-[15px] font-medium text-white/70 hover:text-white relative after:content-[''] after:absolute after:-bottom-1 after:left-0 after:w-0 hover:after:w-full after:h-[2px] after:bg-c-accent after:transition-all after:duration-300 transition-colors duration-300`} href="#about" onClick={(e) => handleNavClick(e, 'about')}>Appointments</a>
        </nav>
        <div className="flex items-center gap-4">
          <button onClick={() => window.dispatchEvent(new Event('open-booking-modal'))} className="btn-primary hidden md:inline-flex">
            Book Consultation
          </button>
          <button
            type="button"
            className="md:hidden relative z-[1] text-white p-1 -mr-1"
            aria-expanded={isMobileMenuOpen}
            aria-label={isMobileMenuOpen ? "Close menu" : "Open menu"}
            onClick={() => setIsMobileMenuOpen((open) => !open)}
          >
            <span className="material-symbols-outlined text-3xl">{isMobileMenuOpen ? 'close' : 'menu'}</span>
          </button>
        </div>
      </div>
    </header>
    {mobileMenu}
    </>
  );
};

export default Navbar;
